/* NEXZO Personalization Engine v152 — account-scoped, cloud-authoritative, live cross-page learning model. */
(function(){
'use strict';
if(window.NEXZOPersonalization?.version>=152)return;
const KEY='nexzo_personalization_v157',LEGACY='nexzo_personalization_v152';
const clamp=(n,a=0,b=100)=>Math.max(a,Math.min(b,Number(n)||0));
const now=()=>Date.now();
const dayKey=(d=new Date())=>{const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};
const clone=v=>JSON.parse(JSON.stringify(v));
const esc=v=>String(v??'').trim();
let activeOwner='local',state=null,cloudTimer=null,cloudUnsub=null,ready=false,switching=false;
const resolveOwner=()=>window.NEXZODataService?.getUser?.()?.uid||window.NEXZOSharedState?.currentUid?.()||window.NEXZOShell?.identity?.()?.uid||'local';
const defaultState=(uid=activeOwner)=>({schemaVersion:157,uid,profile:{course:'',branch:'',semester:'',subjects:[],backlogs:[],examDates:{},careerGoal:'',dailyMinutes:60,language:'Hinglish',explanationStyle:'Concise + examples',confidence:{}},checkins:{},events:[],mastery:{},mistakes:{},recommendations:[],feedback:{},memoryEnabled:true,updatedAtMs:0,cloudUpdatedAtMs:0});
const scopedKey=(uid=activeOwner)=>`${KEY}:${uid}`;
const legacyKey=(uid=activeOwner)=>`${LEGACY}:${uid}`;
function sanitize(raw,uid=activeOwner){const base=defaultState(uid),x=raw&&typeof raw==='object'?raw:{};return {...base,...x,schemaVersion:157,uid,profile:{...base.profile,...(x.profile||{})},checkins:x.checkins||{},events:Array.isArray(x.events)?x.events.slice(-800):[],mastery:x.mastery||{},mistakes:x.mistakes||{},recommendations:Array.isArray(x.recommendations)?x.recommendations:[],feedback:x.feedback||{}}}
function loadLocal(uid=activeOwner){let raw=null;try{raw=JSON.parse(localStorage.getItem(scopedKey(uid))||'null')}catch{};if(!raw){try{raw=JSON.parse(localStorage.getItem(legacyKey(uid))||'null')}catch{}};state=sanitize(raw,uid);return state}
function persistLocal({emit=true,cloud=true}={}){state.uid=activeOwner;state.updatedAtMs=now();localStorage.setItem(scopedKey(),JSON.stringify(state));if(emit)window.dispatchEvent(new CustomEvent('nexzo:personalization-updated',{detail:snapshot()}));if(cloud)scheduleCloud()}
async function cloudContext(){try{const c=await window.NEXZOFirebase?.getContext?.({auth:true,firestore:true});const user=c?.auth?.currentUser;if(!user)return null;return {...c,user}}catch{return null}}
function canonicalToken(v){return esc(v).toLowerCase().replace(/\b(study|revision|revise|practice|practise|learn|learning|notes?|questions?|problems?)\b/g,' ').replace(/[^a-z0-9+#.]+/g,' ').trim().replace(/\s+/g,'-')||'general'}
function normalizeTopic(subject,topic){const sid=canonicalToken(subject||'General'),tid=canonicalToken(topic||subject||'General');return `${sid}::${tid}`}
function assessedEvent(e){return Number.isFinite(Number(e.accuracy))||(Number(e.maxScore)>0&&Number.isFinite(Number(e.score)))}
function topicLabel(key){const [s,t]=String(key).split('::');return {subject:s.replace(/\b\w/g,c=>c.toUpperCase()),topic:t?.replace(/\b\w/g,c=>c.toUpperCase())||s}}
function eventWeight(e){const type=String(e.type||'study');if(type==='quiz')return .34;if(type==='submission')return .32;if(type==='revision')return .2;if(type==='interview')return .22;if(type==='task')return .14;return .1}
function recomputeMastery(){
 const by={};state.events.filter(assessedEvent).forEach(e=>{const key=e.topicKey||normalizeTopic(e.subject,e.topic);(by[key]??=[]).push(e)});const result={};
 Object.entries(by).forEach(([key,events])=>{let totalW=0,weighted=0,last=0,attempts=0,wrong=0;events.sort((a,b)=>(a.atMs||0)-(b.atMs||0)).slice(-30).forEach(e=>{const w=eventWeight(e)*(e.difficulty==='hard'?1.15:e.difficulty==='easy'?.9:1);const acc=Number.isFinite(Number(e.accuracy))?clamp(e.accuracy):clamp(Number(e.score)/Number(e.maxScore)*100);weighted+=acc*w;totalW+=w;attempts++;wrong+=Array.isArray(e.mistakes)?e.mistakes.length:0;last=Math.max(last,e.atMs||0)});let score=totalW?weighted/totalW:0;const days=last?Math.max(0,(now()-last)/86400000):999;score=clamp(score-Math.min(18,Math.max(0,days-7)*.45));const label=topicLabel(key);const assessed=attempts>=2;result[key]={key,...label,score:Math.round(score),assessed,status:!assessed?'Not assessed':score<35?'Critical':score<55?'Weak':score<75?'Improving':'Strong',lastActivityMs:last,attempts,mistakeCount:wrong}});
 (state.profile.subjects||[]).forEach(subject=>{const key=normalizeTopic(subject,subject);if(!result[key])result[key]={key,subject,topic:subject,score:0,assessed:false,status:'Not assessed',lastActivityMs:0,attempts:0,mistakeCount:0}});state.mastery=result;return result;
}
function detectWeaknesses(){recomputeMastery();return Object.values(state.mastery).filter(x=>x.assessed&&x.score<55).sort((a,b)=>a.score-b.score)}
function buildRecommendations(){
 recomputeMastery();const today=state.checkins[dayKey()]||{};const tasks=window.NEXZOTaskStore?.getAll?.()||[];const available=Math.max(15,Number(today.availableMinutes||state.profile.dailyMinutes||60));const energy=String(today.energy||'Normal');const rows=[];
 Object.values(state.mastery).forEach(m=>{let urgency=m.assessed?100-m.score:58;const exam=state.profile.examDates?.[m.subject]||state.profile.examDates?.[m.subject.toLowerCase()];if(exam){const d=(new Date(exam).getTime()-now())/86400000;if(d>=0&&d<=14)urgency+=Math.max(0,40-d*2.5)}const backlog=(state.profile.backlogs||[]).some(x=>String(x).toLowerCase()===m.subject.toLowerCase());if(backlog)urgency+=30;const workload=String(today.workload||'Normal');if(workload==='High')urgency-=8;const focus=String(today.focus||'Adaptive').toLowerCase();if(focus!=='adaptive'&&String(m.topic).toLowerCase().includes(focus))urgency+=10;const pending=tasks.filter(t=>!t.completed&&String(t.subject||'').toLowerCase()===m.subject.toLowerCase()).length;urgency+=Math.min(25,pending*8);const daysSince=m.lastActivityMs?(now()-m.lastActivityMs)/86400000:30;urgency+=Math.min(15,daysSince*.5);const minutes=energy==='Low'?Math.min(30,available):energy==='High'?Math.min(75,available):Math.min(50,available);rows.push({id:`${m.key}:${dayKey()}`,subject:m.subject,topic:m.topic,mastery:m.score,priority:Math.round(urgency),durationMinutes:Math.max(15,Math.round(minutes/5)*5),action:!m.assessed?'Take a short diagnostic':m.score<35?'Rebuild fundamentals + guided practice':m.score<55?'Targeted practice + mistake review':m.score<75?'Mixed practice + recall':'Spaced revision',why:[m.assessed?`Learning mastery ${m.score}%`:'Not assessed yet',backlog?'Backlog priority':null,exam?'Exam/deadline context considered':null,pending?`${pending} pending Planner task${pending>1?'s':''}`:null,m.lastActivityMs?`Last activity ${Math.round(daysSince)} day(s) ago`:'No recent practice'].filter(Boolean)})});rows.forEach(r=>{const f=state.feedback[r.id]?.value;if(f==='not-relevant'||f==='already-know')r.priority-=100;if(f==='too-hard'){r.durationMinutes=Math.max(15,Math.round(r.durationMinutes*.65/5)*5);r.action='Guided fundamentals + easier practice'}if(f==='too-easy')r.priority-=20;if(f==='useful')r.priority+=8});state.recommendations=rows.sort((a,b)=>b.priority-a.priority).slice(0,8);return state.recommendations;
}
function mergeCloud(remote){
 const cloud=sanitize(remote,activeOwner),local=state||defaultState(activeOwner);const cloudStamp=Math.max(Number(remote?.updatedAtMs)||0,Number(remote?.cloudUpdatedAtMs)||0);
 const localStamp=Number(local.updatedAtMs)||0;
 if(cloudStamp>=localStamp){state=cloud;state.cloudUpdatedAtMs=cloudStamp;localStorage.setItem(scopedKey(),JSON.stringify(state));return true}
 // Local is newer: keep local, but merge remote structured events/mistakes to avoid losing another-device activity.
 const eventMap=new Map([...(cloud.events||[]),...(local.events||[])].map(e=>[e.id,e]));state.events=[...eventMap.values()].sort((a,b)=>(a.atMs||0)-(b.atMs||0)).slice(-800);state.mistakes={...(cloud.mistakes||{}),...(local.mistakes||{})};return false;
}
async function pushCloud(){const c=await cloudContext();if(!c||c.user.uid!==activeOwner)return false;try{const ref=c.firestoreTools.doc(c.db,'users',c.user.uid,'personalization','main');const payload={...clone(state),uid:c.user.uid,schemaVersion:157,cloudUpdatedAtMs:now(),updatedAtMs:state.updatedAtMs||now(),updatedAt:c.firestoreTools.serverTimestamp()};await c.firestoreTools.setDoc(ref,payload,{merge:false});state.cloudUpdatedAtMs=payload.cloudUpdatedAtMs;localStorage.setItem(scopedKey(),JSON.stringify(state));window.dispatchEvent(new CustomEvent('nexzo:personalization-sync',{detail:{status:'synced',uid:activeOwner,atMs:now()}}));return true}catch(error){window.dispatchEvent(new CustomEvent('nexzo:personalization-sync',{detail:{status:'offline',uid:activeOwner,error:error?.code||error?.message}}));return false}}
function scheduleCloud(){clearTimeout(cloudTimer);cloudTimer=setTimeout(pushCloud,700)}
async function subscribeCloud(){try{cloudUnsub?.()}catch{};cloudUnsub=null;const c=await cloudContext();if(!c||c.user.uid!==activeOwner)return false;const ref=c.firestoreTools.doc(c.db,'users',activeOwner,'personalization','main');cloudUnsub=c.firestoreTools.onSnapshot(ref,snap=>{if(!snap.exists()){if(state.updatedAtMs)pushCloud();return}const remote=snap.data();const changed=mergeCloud(remote);importPlanner(false);buildRecommendations();if(changed)window.dispatchEvent(new CustomEvent('nexzo:personalization-updated',{detail:snapshot()}));else if((Number(state.updatedAtMs)||0)>(Number(remote?.updatedAtMs)||0))scheduleCloud();window.dispatchEvent(new CustomEvent('nexzo:personalization-sync',{detail:{status:'synced',uid:activeOwner,atMs:now()}}));},()=>window.dispatchEvent(new CustomEvent('nexzo:personalization-sync',{detail:{status:'offline',uid:activeOwner}})));return true}
function updateProfile(patch){state.profile={...state.profile,...clone(patch)};buildRecommendations();persistLocal();return snapshot()}
function dailyCheckin(data){state.checkins[dayKey()]={date:dayKey(),availableMinutes:Math.max(10,Number(data.availableMinutes)||state.profile.dailyMinutes||60),energy:['Low','Normal','High'].includes(data.energy)?data.energy:'Normal',workload:['Low','Normal','High'].includes(data.workload)?data.workload:'Normal',focus:data.focus||'Adaptive',note:esc(data.note).slice(0,300),updatedAtMs:now()};buildRecommendations();persistLocal();return clone(state.checkins[dayKey()])}
function recordEvent(data,{save=true}={}){const e={id:data.id||crypto.randomUUID?.()||`ev_${now()}_${Math.random().toString(36).slice(2)}`,type:data.type||'study',subject:esc(data.subject)||'General',topic:esc(data.topic)||esc(data.subject)||'General',topicKey:normalizeTopic(data.subject,data.topic),score:data.score===null||data.score===undefined?null:Number(data.score),maxScore:data.maxScore===null||data.maxScore===undefined?null:Number(data.maxScore),accuracy:data.accuracy===null||data.accuracy===undefined?null:(Number.isFinite(Number(data.accuracy))?clamp(data.accuracy):null),difficulty:data.difficulty||'medium',durationMinutes:Math.max(0,Number(data.durationMinutes)||0),completed:Boolean(data.completed),mistakes:Array.isArray(data.mistakes)?data.mistakes.map(x=>esc(x)).filter(Boolean).slice(0,10):[],source:data.source||'manual',atMs:Number(data.atMs)||now()};if(state.events.some(x=>x.id===e.id))return e;state.events.push(e);if(state.events.length>800)state.events=state.events.slice(-800);e.mistakes.forEach(m=>{const key=`${e.topicKey}::${m.toLowerCase()}`;const x=state.mistakes[key]||{concept:m,subject:e.subject,topic:e.topic,count:0,lastSeenMs:0};x.count++;x.lastSeenMs=e.atMs;state.mistakes[key]=x});buildRecommendations();if(save)persistLocal();return e}
function importPlanner(save=true){const tasks=window.NEXZOTaskStore?.getAll?.()||[];let added=0;tasks.filter(t=>t.completed).forEach(t=>{const id=`planner:${t.id}:${t.completedAtMs||t.updatedAtMs||0}`;if(state.events.some(e=>e.id===id))return;recordEvent({id,type:'task',subject:t.subject||'General',topic:t.title||t.subject,score:t.score===null||t.score===undefined||t.score===''?null:Number(t.score),maxScore:t.score===null||t.score===undefined||t.score===''?null:10,accuracy:t.score===null||t.score===undefined||t.score===''?null:Number(t.score)*10,difficulty:t.difficulty||t.level||'medium',durationMinutes:Number(t.actualMinutes)||Math.round((Number(t.elapsed)||0)/60000),completed:true,source:'planner',atMs:t.completedAtMs||t.updatedAtMs||now()},{save:false});added++});if(added&&save)persistLocal();return added}
function feedback(id,value){state.feedback[id]={value,atMs:now()};persistLocal()}
function forget(section){if(section==='all')state=defaultState(activeOwner);else if(section==='events'){state.events=[];state.mastery={};state.mistakes={};state.recommendations=[]}else if(section==='profile')state.profile=defaultState(activeOwner).profile;else if(section==='mistakes')state.mistakes={};buildRecommendations();persistLocal()}
function snapshot(){if(!state)state=defaultState(activeOwner);recomputeMastery();buildRecommendations();return clone({...state,weakTopics:Object.values(state.mastery).filter(x=>x.assessed&&x.score<55).sort((a,b)=>a.score-b.score)})}
async function switchOwner(force=false){if(switching)return;const next=resolveOwner();if(!force&&next===activeOwner&&ready)return;switching=true;try{activeOwner=next;loadLocal(next);importPlanner(false);buildRecommendations();ready=true;window.dispatchEvent(new CustomEvent('nexzo:personalization-ready',{detail:snapshot()}));if(next!=='local')await subscribeCloud()}finally{switching=false}}
async function init(){await switchOwner(true);setTimeout(()=>switchOwner(),800);setTimeout(()=>switchOwner(),2500)}
window.NEXZOPersonalization=Object.freeze({version:157,init,snapshot,updateProfile,dailyCheckin,recordEvent,importPlanner,recomputeMastery,detectWeaknesses,buildRecommendations,feedback,forget,pushCloud,switchOwner,get ready(){return ready},get uid(){return activeOwner}});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
['nexzo:data-ready','nexzo:auth-ready','nexzo:profile-updated'].forEach(name=>window.addEventListener(name,()=>switchOwner()));

window.addEventListener('nexzo:ai-learning-complete',e=>{if(!ready)return;const d=e.detail||{};recordEvent({id:d.id||`ai:${d.kind}:${now()}`,type:d.kind==='interview'?'interview':'quiz',subject:d.subject||'Study Assistant',topic:d.topic||d.subject||'Study Assistant',accuracy:Number.isFinite(Number(d.score))?Number(d.score):null,difficulty:d.difficulty||'medium',completed:true,mistakes:Array.isArray(d.mistakes)?d.mistakes:[],source:'assistant'});});
window.addEventListener('nexzo:assistant-feedback',e=>{if(!ready)return;const d=e.detail||{};if(!d.id)return;state.feedback[d.id]={value:d.value||'cleared',kind:'assistant-response',chatId:d.chatId||'',messageId:d.messageId||'',atMs:Number(d.atMs)||now()};persistLocal();});

window.addEventListener('nexzo:task-store',()=>{if(ready){const added=importPlanner(false);buildRecommendations();if(added)persistLocal()}});
})();
